import {renderDrcBenchmark} from './drc-lab.js';
export {setDrcBenchmark} from './drc-lab.js';
let evidence = null;
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num = value => Number(value).toFixed(3);
export function setMeteredEvidence(data) { evidence = data; }

function diagnosticChart(runs) {
  const max = Math.max(...runs.flatMap(r => [r.repeat_first_day.mae_pp, r.flat.mae_pp])) * 1.15;
  return '<svg class="meter-chart" viewBox="0 0 700 260" role="img" aria-label="Hourly current-share MAE for four later days. Repeating the first day has lower MAE than a flat profile in these four comparisons; this is one site only.">' + runs.map((r, i) => {
    const y = 25 + i * 58;
    return '<text x="0" y="' + (y + 18) + '">' + esc(r.series) + ' · day ' + r.test_complete_day + '</text><rect x="170" y="' + y + '" width="' + (r.repeat_first_day.mae_pp / max * 410) + '" height="15" rx="3" fill="#41694a"/><text x="' + (178 + r.repeat_first_day.mae_pp / max * 410) + '" y="' + (y + 12) + '">' + num(r.repeat_first_day.mae_pp) + '</text><rect x="170" y="' + (y + 20) + '" width="' + (r.flat.mae_pp / max * 410) + '" height="15" rx="3" fill="#d4ba90"/><text x="' + (178 + r.flat.mae_pp / max * 410) + '" y="' + (y + 32) + '">' + num(r.flat.mae_pp) + '</text>';
  }).join('') + '</svg>';
}

export function renderMeteredLab() {
  if (!evidence) return renderDrcBenchmark() + '<div class="info-note">Tanzania metered evidence could not load. Refresh the app while online, then refresh the offline pack.</div>';
  const d = evidence.dataset, e = evidence.evaluation;
  return renderDrcBenchmark() + '<div class="view-heading"><h2>Tanzania: measured current, clear boundaries.</h2><p>A reproducible meter-data diagnostic, separate from both household ML benchmarks and village scenarios.</p></div>' +
    '<div class="evidence-grid"><section class="panel evidence-card"><div class="number">' + Number(d.rows).toLocaleString('en-US') + '</div><h3>Minute current records acquired</h3><p>Nine series from one operating Tanzania mini-grid. Original ZIP verified against the publisher’s SHA-256.</p></section><section class="panel evidence-card"><div class="number">' + e.test_days + '</div><h3>Later complete days evaluated</h3><p>First complete day trains each recording. Every later complete day is evaluated: 96 hourly bins, all from the same site.</p></section><section class="panel evidence-card"><div class="number">0</div><h3>Unseen-site kWh tests</h3><p>This diagnostic does not validate the household forest, RAMP, Lamwo energy estimates or demand growth.</p></section></div>' +
    '<div class="meter-verdict"><span class="head-tag">RETROSPECTIVE · ONE SITE</span><h3>A familiar daily rhythm helps—until a larger error matters.</h3><p>Repeating the first day’s shape beats a flat profile on MAE in all four comparisons. On Minigrid1b day 2, it has <strong>worse RMSE</strong>. We retain that result. No machine-learning accuracy claim follows from this simple timing diagnostic.</p></div>' +
    '<div class="meter-grid"><section class="panel"><div class="panel-head"><div><h2>Timing-shape diagnostic</h2><p class="subtext">Mean absolute error · percentage points of daily current share</p></div></div><div class="meter-body"><div class="meter-legend"><span><i style="background:#41694a"></i>Repeat first complete day</span><span><i style="background:#d4ba90"></i>Flat 1/24 baseline</span></div>' + diagnosticChart(e.runs) + '<p class="control-help">Lower is better. This tests the distribution across 24 hours, not the size of the next day’s electricity demand. Current shares are not energy shares.</p></div></section>' +
    '<section class="panel"><div class="panel-head"><h2>What we can conclude</h2></div><div class="meter-body"><p><strong>Measured current exists.</strong> We acquired and audited the source instead of relabelling synthetic profiles as observed data.</p><p><strong>The comparison is deliberately simple.</strong> It exposes a daily-pattern baseline and a case where a larger error reverses the ranking.</p><p><strong>The challenge’s key test remains open.</strong> Cold-start demand needs matched preconnection features and measured customer kWh from entirely held-out sites.</p><a class="btn" href="./data/metered-evidence.json" download="AimEnergy-metered-evidence.json">Download evidence & metrics</a></div></section></div>' +
    '<section class="panel source-list"><div class="panel-head"><div><h2>Complete result ledger</h2><p class="subtext">Both recordings represent the same aggregate meter entity; they are not two independent sites.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Recording / later day</th><th>Repeat MAE (pp)</th><th>Flat MAE (pp)</th><th>Repeat RMSE (pp)</th><th>Flat RMSE (pp)</th><th>RMSE comparison</th></tr></thead><tbody>' + e.runs.map(r => '<tr><td>' + esc(r.series) + ' / day ' + r.test_complete_day + '</td><td>' + num(r.repeat_first_day.mae_pp) + '</td><td>' + num(r.flat.mae_pp) + '</td><td>' + num(r.repeat_first_day.rmse_pp) + '</td><td>' + num(r.flat.rmse_pp) + '</td><td><span class="head-tag ' + (r.repeat_first_day.rmse_pp > r.flat.rmse_pp ? 'meter-worse' : '') + '">' + (r.repeat_first_day.rmse_pp > r.flat.rmse_pp ? 'Worse than flat' : 'Lower than flat') + '</span></td></tr>').join('') + '</tbody></table></div></section>' +
    '<section class="panel source-list"><div class="panel-head"><h2>Source and interpretation</h2></div><div class="meter-body"><p><a href="' + esc(d.url) + '" target="_blank" rel="noopener noreferrer">Hartvigsson & Ahlgren · Mendeley Data · 2018</a> · DOI ' + esc(d.doi) + ' · ' + esc(d.license) + '.</p><p>Measured one-phase current in amperes. Concurrent measured voltage and power factor are absent, so we do not convert it to kWh. Headers are inferred from the paper and numeric ordering; the reported “average” equals the midpoint of minimum and maximum within rounding. Absolute dates and timezone are unavailable.</p><p><strong>Reproduce:</strong> run <code>python scripts/acquire_tanzania_data.py</code>, then <code>python scripts/build_metered_benchmark.py</code>. Raw records remain in the local Data folder. The source audit records hashes, elapsed-minute splits and data-quality issues.</p><details><summary>Full diagnostic protocol and limitations</summary><p>' + esc(evidence.protocol.split) + ' ' + esc(evidence.protocol.prediction) + '</p><ul>' + evidence.limitations.map(x => '<li>' + esc(x) + '</li>').join('') + '</ul><p>' + esc(d.attribution) + '</p></details></div></section>' +
    '<section class="panel source-list"><div class="panel-head"><h2>The next experiment: unseen villages</h2></div><div class="meter-body"><p>Before fitting: agree the customer-consumption target, freeze site groups and baselines, separate supply-constrained periods, and set acceptance thresholds with an operator. Evaluate energy, signed bias, growth and interval coverage on untouched sites.</p><p>The submission includes a concrete aggregate-data template and pilot protocol in <code>docs/PILOT_PROTOCOL.md</code>. No operator partnership or field measurement is implied.</p><button class="btn" data-action="nav" data-view="field">Inspect the field assessment workflow →</button></div></section>';
}
